// 复习
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin.exceptions(ios::badbit | ios::failbit);

    int n;
    cin >> n;
    vector<int> pos(n+1); vector<long long> f(n+1);
    for (int i=1; i<=n; i++) {
        int x; cin >> x; pos[x] = i;
    }
    
    FenwickTree<long long> invCnt(n), posSum(n);
    long long preInv = 0;

    for (int k=1; k<=n; k++) {
        auto p = pos[k];
        preInv += invCnt.query(p+1, n);

        invCnt.update(p, 1); posSum.update(p, p);
        auto llen = (k + 1) / 2, rlen = k / 2;
        int lo = 1, hi = n;
        while (lo <= hi) {
            auto mid = (lo + hi) / 2;
            if (invCnt.pre(mid) >= llen) hi = mid-1;
            else lo = mid + 1;
        }
        long long x = hi + 1;

        auto lcost = (x + x + 1 - llen) * llen / 2 - posSum.pre(x);
        auto rcost = posSum.query(x+1, n) - (x + 1 + x + rlen) * rlen / 2;

        f[k] = preInv + lcost + rcost;
    }
    
    for (int k=1; k<=n; k++) {
        cout << f[k] << " \n"[k==n];
    }

    return 0;
}